// Generated by Cypress Author — 2026-08-31
// Bug report: on the information page of an ERP/Cellule établissement, the
// "Types & activités" block lists one or several "{type} - {activité}" lines.
// When opening "Modifier la fiche", the ID_TYPE select is correctly pre-filled
// but the corresponding ID_TYPEACTIVITE select always resets to the first
// option of the activités list instead of keeping the saved value.
describe('Établissement — cohérence Types & activités entre la fiche et le formulaire de modification', () => {
    beforeEach(() => {
        cy.login()
    })

    /**
     * Extrait, pour un <li> de la liste "Types & activités" de la fiche
     * établissement, le libellé du type (via l'attribut title de l'icône
     * s'il existe, sinon via le texte) et le libellé de l'activité.
     *
     * @param {JQuery<HTMLLIElement>} $li
     * @returns {{type: string, activite: string}}
     */
    function extraireLigneTypeActivite($li) {
        const raw = $li.text().replace(/\s+/g, ' ').trim()
        const dashIndex = raw.indexOf('-')
        const activite = (dashIndex >= 0 ? raw.slice(dashIndex + 1) : raw).replace(/^-+/, '').trim()

        const $img = $li.find('img')
        const type = $img.length
            ? ($img.attr('title') || '').trim()
            : (dashIndex >= 0 ? raw.slice(0, dashIndex).trim() : raw.trim())

        return { type, activite }
    }

    it('Fiche établissement → formulaire de modification : les activités sélectionnées correspondent à la fiche', () => {
        // 1. Recherche des établissements de genre "ERP" (genres[]=2)
        cy.visit('/rechercher/etablissement?label=&Rechercher=Rechercher&page=1&zone_de_recherche_text=&city=&street=&number=&genres%5B%5D=2&preventionniste=')
        cy.get('ul.recherche_liste li.etablissement').should('have.length.gte', 1)

        // 2. Ouverture de la fiche du premier résultat
        cy.get('ul.recherche_liste li.etablissement').first()
            .find('span.nom-etablissement a').click()
        cy.url().should('include', '/etablissement/')

        // 3. Lecture des lignes "Types & activités" affichées sur la fiche
        cy.contains('dt', 'Types & activités')
            .closest('dl')
            .find('dd ul.list-unstyled > li')
            .should('have.length.gte', 1)
            .then($lis => {
                const lignesAttendues = Cypress._.map($lis.toArray(), li => extraireLigneTypeActivite(Cypress.$(li)))

                // 4. Passage en édition
                cy.contains('Modifier la fiche').click()
                cy.url().should('include', '/modifier')

                // 5. Vérification que chaque select ID_TYPE / ID_TYPEACTIVITE
                // (principal puis secondaires, dans l'ordre d'affichage) reflète
                // bien la valeur enregistrée et affichée sur la fiche.
                cy.get('#activite_ul > li').not('.prototype').should('have.length', lignesAttendues.length)

                cy.get('#activite_ul > li').not('.prototype').each(($li, index) => {
                    const attendu = lignesAttendues[index]

                    cy.wrap($li).find('select.type_select option:selected')
                        .invoke('text').then(texte => texte.trim())
                        .should('eq', attendu.type)

                    cy.wrap($li).find('select.activite_select option:selected')
                        .invoke('text').then(texte => texte.trim())
                        .should('eq', attendu.activite)
                })
            })
    })
})
